-- Seed official D&D 5e Spells from Xanathar's Guide to Everything (XGE) & Tasha's Cauldron of Everything (TCE) in Portuguese

-- Truques (Cantrips)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Lâmina Estrondosa (Booming Blade)', 0, 'Evocação', '1 ação', 'Pessoal (alcance de 1,5m)', 'S, M (uma arma corpo a corpo)', '1 rodada', 'Você brande a arma usada na conjuração e faz um ataque corpo a corpo com ela contra uma criatura a até 1,5 metro de você. Em caso de acerto, o alvo sofre os efeitos normais do ataque e fica envolto por uma energia trovejante até o início do seu próximo turno. Se o alvo se mover voluntariamente 1,5 metro ou mais antes disso, ele sofre 1d8 de dano trovejante imediatamente, e a magia se encerra.

No 5º nível, o ataque corpo a corpo causa 1d8 de dano trovejante adicional ao acertar, e o dano sofrido pelo alvo por se mover aumenta para 2d8. Ambos os danos aumentam em 1d8 no 11º nível (2d8/3d8) e 17º nível (3d8/4d8).', false),
  (null, 'dnd5e', 'Lâmina da Chama Verde (Green-Flame Blade)', 0, 'Evocação', '1 ação', 'Pessoal (alcance de 1,5m)', 'S, M (uma arma corpo a corpo)', 'Instantânea', 'Você brande a arma usada na conjuração e faz um ataque corpo a corpo com ela contra uma criatura a até 1,5 metro de você. Em caso de acerto, o alvo sofre os efeitos normais do ataque e chamas verdes saltam do alvo para uma criatura diferente à sua escolha que você possa ver a até 1,5 metro dele. A segunda criatura sofre dano de fogo igual ao seu modificador de habilidade de conjuração.

No 5º nível, o ataque causa 1d8 de dano de fogo adicional ao alvo inicial, e o dano na segunda criatura aumenta para 1d8 + seu modificador de habilidade de conjuração. Ambos os danos aumentam em 1d8 no 11º nível (2d8) e 17º nível (3d8).', false),
  (null, 'dnd5e', 'Estilhaço Mental (Mind Sliver)', 0, 'Encantamento', '1 ação', '18 metros', 'V', '1 rodada', 'Você crava um pico desorientador de energia psíquica na mente de uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Inteligência ou sofrerá 1d6 de dano psíquico e subtrairá 1d4 da próxima salvaguarda que fizer antes do final do seu próximo turno.

O dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Golpe Primitivo (Primal Savagery)', 0, 'Transmutação', '1 ação', 'Pessoal', 'S', 'Instantânea', 'Você canaliza a ferocidade primordial para transformar seus dentes ou unhas em armas corrosivas e afiadas. Faça um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro de você. Em caso de acerto, o alvo sofre 1d10 de dano ácido.

O dano desta magia aumenta em 1d10 quando você alcança o 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).', false),
  (null, 'dnd5e', 'Infestação (Infestation)', 0, 'Conjuração', '1 ação', '9 metros', 'V, S, M (uma pulga viva)', 'Instantânea', 'Você faz com que uma nuvem de ácaros, pulgas e outros parasitas surja momentaneamente sobre uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Constituição ou sofrerá 1d6 de dano veneno e se moverá 1,5 metro em uma direção aleatória se puder se mover.

O dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Rajada de Espadas (Sword Burst)', 0, 'Conjuração', '1 ação', 'Pessoal (raio de 1,5m)', 'V', 'Instantânea', 'Você cria um círculo momentâneo de lâminas espectrais que varrem tudo ao seu redor. Todas as outras criaturas a até 1,5 metro de você devem ser bem-sucedidas em uma salvaguarda de Destreza ou sofrerão 1d6 de dano de energia.

O dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Pancada do Trovão (Thunderclap)', 0, 'Evocação', '1 ação', 'Pessoal (raio de 1,5m)', 'S', 'Instantânea', 'Você cria uma explosão de som trovejante que pode ser ouvida a até 30 metros de distância. Cada criatura a até 1,5 metro de você, exceto você, deve fazer uma salvaguarda de Constituição. Se falhar, a criatura sofre 1d6 de dano trovejante.

O dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Palavra de Resplandecência (Word of Radiance)', 0, 'Evocação', '1 ação', 'Pessoal (raio de 1,5m)', 'V, M (um símbolo sagrado)', 'Instantânea', 'Você profere uma palavra divina e um brilho radiante queima ao seu redor. Cada criatura à sua escolha que você possa ver a até 1,5 metro de você deve ser bem-sucedida em uma salvaguarda de Constituição ou sofrerá 1d6 de dano radiante.

O dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Moldar Terra (Mold Earth)', 0, 'Transmutação', '1 ação', '9 metros', 'S', 'Instantânea ou 1 hora', 'Você escolhe uma porção de terra ou pedra que possa ver dentro do alcance e manipula-a das seguintes formas: escavar terra solta até um cubo de 1,5m instantaneamente, fazer formas ou cores surgirem na superfície por 1 hora, ou transformar terreno plano em terreno difícil (ou vice-versa) por 1 hora.', false),
  (null, 'dnd5e', 'Moldar Água (Shape Water)', 0, 'Transmutação', '1 ação', '9 metros', 'S', 'Instantânea ou 1 hora', 'Você escolhe uma área de água que possa ver dentro do alcance que caiba em um cubo de 1,5 metro e pode: mover ou mudar o fluxo da água em até 1,5 metro em qualquer direção, fazer a água formar formas simples e animadas por 1 hora, mudar a cor ou opacidade da água por 1 hora, ou congelar a água desde que não haja criaturas dentro dela por 1 hora.', false),
  (null, 'dnd5e', 'Controle de Chamas (Control Flames)', 0, 'Transmutação', '1 ação', '18 metros', 'S', 'Instantânea ou 1 hora', 'Você escolhe uma chama não mágica que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro para: expandir o fogo em 1,5m em uma direção com combustível, extinguir as chamas no cubo, dobrar ou reduzir pela metade a iluminação gerada pelo fogo, ou fazer formas animadas simples aparecerem no fogo por 1 hora.', false),
  (null, 'dnd5e', 'Tromba de Ar (Gust)', 0, 'Transmutação', '1 ação', '9 metros', 'V, S', 'Instantânea', 'Você agarra o ar e cria uma lufada de vento em um ponto dentro do alcance que pode empurrar uma criatura Média ou menor que falhe em uma salvaguarda de Força a até 1,5m de distância, mover um objeto de até 2,5 kg a até 3m de distância, ou criar um efeito sensorial inofensivo com o vento.', false),
  (null, 'dnd5e', 'Toque Gélido / Queimadura de Gelo (Frostbite)', 0, 'Evocação', '1 ação', '18 metros', 'V, S', 'Instantânea', 'Você faz com que uma geada entorpecente cubra uma criatura que você possa ver dentro do alcance. O alvo deve fazer uma salvaguarda de Constituição. Se falhar, sofre 1d6 de dano de frio e tem desvantagem na próxima jogada de ataque com arma que fizer antes do final do seu próximo turno.

O dano aumenta em 1d6 no 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).', false),
  (null, 'dnd5e', 'Criar Fogueira (Create Bonfire)', 0, 'Conjuração', '1 ação', '18 metros', 'V, S', 'Concentração, até 1 minuto', 'Você cria uma fogueira mágica no chão em um ponto que você possa ver dentro do alcance. Qualquer criatura no espaço da fogueira quando você conjura a magia deve ser bem-sucedida em uma salvaguarda de Destreza ou sofrerá 1d8 de dano de fogo. Uma criatura também deve fazer a salvaguarda quando entra no espaço da fogueira pela primeira vez em um turno ou termina seu turno lá.

O dano da magia aumenta em 1d8 no 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).', false);

-- 1º Nível (1st Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Absorver Elementos (Absorb Elements)', 1, 'Abjuração', '1 reação (ao sofrer dano de ácido, frio, fogo, elétrico ou trovão)', 'Pessoal', 'S', '1 rodada', 'A magia captura parte da energia recebida, diminuindo seu impacto em você e armazenando-a para o seu próximo ataque corpo a corpo. Você tem resistência ao tipo de dano que ativou a reação até o início do seu próximo turno. Além disso, na primeira vez que você acertar um ataque corpo a corpo no seu próximo turno, o alvo sofre 1d6 de dano extra do tipo correspondente.

Em Círculos Superiores. O dano extra aumenta em 1d6 para cada círculo do espaço de magia acima do 1º.', false),
  (null, 'dnd5e', 'Fera Vínculo (Beast Bond)', 1, 'Adivinhação', '1 ação', 'Toque', 'V, S, M (uma mecha de pelos)', 'Concentração, até 10 minutos', 'Você estabelece uma ligação telepática com uma fera que você toque que seja amigável ou enfeitiçada por você. Enquanto a magia durar, a ligação permanece ativa enquanto os dois estiverem à vista um do outro. Através do vínculo, a fera pode entender suas mensagens telepáticas e você pode perceber suas respostas emocionais e pensamentos simples. Enquanto a fera puder ver você, ela tem vantagem nas jogadas de ataque contra qualquer criatura a até 1,5m de você.', false),
  (null, 'dnd5e', 'Catapulta (Catapult)', 1, 'Transmutação', '1 ação', '27 metros', 'S', 'Instantânea', 'Escolha um objeto de 0,5 kg a 2,5 kg dentro do alcance que não esteja sendo vestido ou carregado. O objeto voa em linha reta até 27 metros em uma direção à sua escolha antes de cair no chão, parando prematuramente se atingir uma superfície sólida ou criatura. Se atingir uma criatura, ela deve fazer uma salvaguarda de Destreza. Se falhar, o objeto e a criatura sofrem 3d8 de dano contundente cada.

Em Círculos Superiores. O peso máximo permitido do objeto aumenta em 2,5 kg e o dano aumenta em 1d8 para cada círculo acima do 1º.', false),
  (null, 'dnd5e', 'Causar Medo (Cause Fear)', 1, 'Necromancia', '1 ação', '18 metros', 'V', 'Concentração, até 1 minuto', 'Você desperta a sensação de mortalidade iminente em uma criatura à sua vista no alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará amedrontado por você enquanto a magia durar. O alvo amedrontado pode repetir a salvaguarda no final de cada um dos seus turnos, encerrando o efeito sobre si em caso de sucesso.

Em Círculos Superiores. Você pode escolher uma criatura adicional como alvo para cada círculo acima do 1º.', false),
  (null, 'dnd5e', 'Cerimônia (Ceremony)', 1, 'Abjuração', '1 hora (Ritual)', 'Toque', 'V, S, M (25 po de pó de prata)', 'Instantânea', 'Você realiza um rito religioso especial. Ao conjurar a magia, escolha um dos seguintes ritos: Expiação, Água Benta, Consagração de Casamento, Sepultamento Sagrado, Investidura de Clérigo ou Rito de Passagem, concedendo bênçãos sagradas e benefícios mecânicos únicos aos participantes.', false),
  (null, 'dnd5e', 'Raio do Caos (Chaos Bolt)', 1, 'Evocação', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Você dispara uma massa ondulante e caótica de energia contra uma criatura dentro do alcance. Faça um ataque mágico à distância. Em caso de acerto, o alvo sofre 2d8 + 1d6 de dano. Escolha um dos dados de d8; o número rolado determina o tipo de dano (Ácido, Frio, Fogo, Energia, Elétrico, Veneno, Psíquico ou Trovão). Se você rolar o mesmo número em ambos os d8s, a energia caótica salta para um novo alvo a até 9m.', false),
  (null, 'dnd5e', 'Faca de Gelo (Ice Knife)', 1, 'Conjuração', '1 ação', '18 metros', 'S, M (uma gota de água ou pedaço de gelo)', 'Instantânea', 'Você cria um estilhaço afiado de gelo e o arremessa contra uma criatura dentro do alcance. Faça um ataque mágico à distância. Em caso de acerto, o alvo sofre 1d10 de dano perfurante. Acertando ou errando, o estilhaço então explode em fragmentos gélidos. O alvo e cada criatura a até 1,5 metro de onde o gelo explodiu devem ser bem-sucedidos em uma salvaguarda de Destreza ou sofrerão 2d6 de dano de frio.

Em Círculos Superiores. O dano de frio aumenta em 1d6 para cada círculo acima do 1º.', false),
  (null, 'dnd5e', 'Armadilha de Laço (Snare)', 1, 'Abjuração', '1 minuto', 'Toque', 'S, M (7,5m de corda)', 'Até ser dissipada ou acionada', 'Ao conjurar a magia, você usa uma corda para criar uma armadilha mágica circular de 1,5m de raio no chão ou solo. A armadilha fica invisível. Quando uma criatura Pequena, Média ou Grande entra na área, ela deve fazer uma salvaguarda de Destreza. Se falhar, é içada de cabeça para baixo a até 1,5m de altura e fica impedida até se libertar.', false),
  (null, 'dnd5e', 'Tremor de Terra (Earth Tremor)', 1, 'Evocação', '1 ação', 'Pessoal (raio de 3m)', 'V, S', 'Instantânea', 'Você faz com que uma onda de tremor sísmico irrompa no chão ao seu redor. Cada criatura a até 3 metros de você, exceto você, deve fazer uma salvaguarda de Destreza. Se falhar, sofre 1d6 de dano contundente e cai no chão (derrubada). O solo na área se torna terreno difícil.

Em Círculos Superiores. O dano aumenta em 1d6 para cada círculo acima do 1º.', false),
  (null, 'dnd5e', 'Ataque do Zéfiro (Zephyr Strike)', 1, 'Transmutação', '1 ação bônus', 'Pessoal', 'V', 'Concentração, até 1 minuto', 'Você se move como o vento. Enquanto a magia durar, seu movimento não provoca ataques de oportunidade. Além disso, uma vez antes da magia acabar, você pode se conceder vantagem em uma jogada de ataque com arma no seu turno. Esse ataque causa 1d8 de dano de energia extra ao acertar, e seu deslocamento aumenta em 9 metros até o final daquele turno.', false),
  (null, 'dnd5e', 'Mistura Cáustica de Tasha (Tasha''s Caustic Brew)', 1, 'Evocação', '1 ação', 'Pessoal (linha de 9 metros)', 'V, S, M (um pedaço de comida podre)', 'Concentração, até 1 minuto', 'Uma correnteza de ácido é expelida de suas mãos em uma linha de 9 metros de comprimento e 1,5 metro de largura. Cada criatura na linha deve ser bem-sucedida em uma salvaguarda de Destreza ou ficará coberta de ácido. Uma criatura coberta sofre 2d4 de dano ácido no início de cada um de seus turnos até que ela ou outra criatura use uma ação para raspar ou lavar o ácido.

Em Círculos Superiores. O dano aumenta em 2d4 para cada círculo acima do 1º.', false);

-- 2º Nível (2nd Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Chicote Mental de Tasha (Tasha''s Mind Whip)', 2, 'Encantamento', '1 ação', '27 metros', 'V', '1 rodada', 'Você desfere um chicote psíquico na mente de uma criatura à sua vista dentro do alcance. O alvo deve fazer uma salvaguarda de Inteligência. Se falhar, sofre 3d6 de dano psíquico e, no próximo turno dele, ele não pode usar reações, seu deslocamento é reduzido pela metade e ele pode realizar apenas uma Ação, uma Ação Bônus ou seu Movimento (apenas um dos três).

Em Círculos Superiores. Você pode alvejar uma criatura adicional a até 9m de outro alvo para cada círculo acima do 2º.', false),
  (null, 'dnd5e', 'Lâmina das Sombras (Shadow Blade)', 2, 'Ilusão', '1 ação bônus', 'Pessoal', 'V, S', 'Concentração, até 1 minuto', 'Você tece fios de sombra para criar uma espada de pura escuridão em sua mão livre. Esta lâmina mágica dura até o término da magia. Ela conta como uma arma corpo a corpo simples com a qual você é proficiente, com as propriedades leve, acuidade e arremesso (alcance 6m/18m). Ela causa 2d8 de dano psíquico ao acertar. Quando você a usa contra um alvo em penumbra ou escuridão, você tem vantagem na jogada de ataque.

Em Círculos Superiores. O dano aumenta para 3d8 (3º/4º círculo), 4d8 (5º/6º círculo) e 5d8 (7º círculo ou superior).', false),
  (null, 'dnd5e', 'Espiga Mental (Mind Spike)', 2, 'Adivinhação', '1 ação', '18 metros', 'S', 'Concentração, até 1 hora', 'Você crava um espinho de energia psíquica na mente de uma criatura dentro do alcance. O alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, sofre 3d8 de dano psíquico e você sempre sabe a localização exata do alvo enquanto a magia durar, impedindo-o de se esconder ou ficar invisível para você.

Em Círculos Superiores. O dano aumenta em 1d8 para cada círculo acima do 2º.', false),
  (null, 'dnd5e', 'Sopro do Dragão (Dragon''s Breath)', 2, 'Transmutação', '1 ação bônus', 'Toque', 'V, S, M (uma pimenta picante)', 'Concentração, até 1 minuto', 'Você toca uma criatura voluntária e a imbui com o poder de cuspir energia. Escolha ácido, frio, fogo, elétrico ou veneno. Enquanto a magia durar, a criatura pode usar uma ação para exalar um cone de 4,5 metros de energia. Cada criatura no cone deve fazer uma salvaguarda de Destreza, sofrendo 3d6 de dano do tipo escolhido se falhar, ou metade se passar.

Em Círculos Superiores. O dano aumenta em 1d6 para cada círculo acima do 2º.', false),
  (null, 'dnd5e', 'Espírito Curador (Healing Spirit)', 2, 'Conjuração', '1 ação bônus', '18 metros', 'V, S', 'Concentração, até 1 minuto', 'Você invoca um espírito da natureza intangível em um espaço de 1,5 metro dentro do alcance. Sempre que você ou uma criatura que você possa ver entrar no espaço do espírito pela primeira vez em um turno ou iniciar seu turno lá, você pode fazer com que o espírito cure 1d6 pontos de vida daquela criatura. O espírito pode curar um número de vezes igual a 1 + seu modificador de habilidade de conjuração (mínimo 2 vezes) antes de desaparecer. Como ação bônus, você pode mover o espírito até 9 metros.', false),
  (null, 'dnd5e', 'Invocar Fera (Summon Beast)', 2, 'Conjuração', '1 ação', '27 metros', 'V, S, M (uma pena, mecha de pelo e um raminho em um frasco de 200 po)', 'Concentração, até 1 hora', 'Você invoca um espírito bestial que assume uma forma física de uma fera (Terra, Ar ou Água). A criatura é um aliado fiel que obedece aos seus comandos no combate, agindo logo após o seu turno na iniciativa.', false),
  (null, 'dnd5e', 'Vento Protetor (Warding Wind)', 2, 'Evocação', '1 ação', 'Pessoal', 'V', 'Concentração, até 10 minutos', 'Um vento forte (30 km/h) sopra ao seu redor em um raio de 3 metros e se move com você. O vento ensurdece você e as outras criaturas na área, extingue chamas desprotegidas, dispersa gases e vapores, torna a área terreno difícil para outras criaturas e impõe desvantagem em ataques com armas à distância que passem por dentro ou para fora do vento.', false),
  (null, 'dnd5e', 'Garra de Terra de Maximilian (Maximilian''s Earthen Grasp)', 2, 'Transmutação', '1 ação', '9 metros', 'V, S, M (uma mão esculpida em argila)', 'Concentração, até 1 minuto', 'Você escolhe um espaço desocupado de 1,5 metro no chão para fazer uma mão de terra compactada e pedra brotar do solo. A mão pode agarrar e esmagar uma criatura que falhe em uma salvaguarda de Força, causando 2d6 de dano contundente e mantendo-a impedida até se libertar.', false);

-- 3º Nível (3rd Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Passo do Trovão (Thunder Step)', 3, 'Conjuração', '1 ação', '27 metros', 'V', 'Instantânea', 'Você se teleporta instantaneamente para um espaço desocupado que possa ver a até 27 metros de distância. Imediatamente após desaparecer, um estrondo trovejante ecoa no espaço que você deixou. Cada criatura a até 3 metros daquele espaço deve fazer uma salvaguarda de Constituição. Se falhar, sofre 3d10 de dano trovejante (ou metade em caso de sucesso). Você pode levar consigo uma criatura voluntária de tamanho igual ou menor que o seu.

Em Círculos Superiores. O dano aumenta em 1d10 para cada círculo acima do 3º.', false),
  (null, 'dnd5e', 'Erupção Telúrica (Erupting Earth)', 3, 'Transmutação', '1 ação', '36 metros', 'V, S, M (um pedaço de obsidiana)', 'Instantânea', 'Você escolhe um ponto no solo dentro do alcance. Uma fonte de terra batida e rochas pontiagudas explode em um cubo de 6 metros. Cada criatura na área deve fazer uma salvaguarda de Destreza, sofrendo 3d12 de dano contundente se falhar, ou metade se passar. O solo se torna terreno difícil.

Em Círculos Superiores. O dano aumenta em 1d12 para cada círculo acima do 3º.', false),
  (null, 'dnd5e', 'Transferência de Vida (Life Transference)', 3, 'Necromancia', '1 ação', '9 metros', 'V, S', 'Instantânea', 'Você sacrifica parte de sua própria vitalidade para curar outra criatura. Você sofre 4d8 de dano necrótico que não pode ser reduzido ou evitado de nenhuma forma. Uma criatura à sua escolha dentro do alcance recupera uma quantidade de pontos de vida igual ao dobro do dano necrótico que você sofreu.

Em Círculos Superiores. O dano que você sofre (e consequentemente a cura recebida pelo alvo) aumenta em 1d8 para cada círculo acima do 3º.', false),
  (null, 'dnd5e', 'Inimigos Abundantes (Enemies Abound)', 3, 'Encantamento', '1 ação', '36 metros', 'V, S', 'Concentração, até 1 minuto', 'Você atinge a mente de uma criatura dentro do alcance, fazendo com que ela perca a capacidade de distinguir amigos de inimigos. O alvo deve fazer uma salvaguarda de Inteligência. Se falhar, o alvo passa a enxergar todas as criaturas como inimigos mortais e deve atacar a criatura mais próxima sempre que puder.', false),
  (null, 'dnd5e', 'Invocar Feérico (Summon Fey)', 3, 'Conjuração', '1 ação', '27 metros', 'V, S, M (uma flor dourada de 300 po)', 'Concentração, até 1 hora', 'Você invoca um espírito feérico com habilidades ilusórias e ataques velozes que obedece aos seus comandos durante o combate.', false),
  (null, 'dnd5e', 'Invocar Morto-Vivo (Summon Undead)', 3, 'Necromancia', '1 ação', '27 metros', 'V, S, M (uma caveira dourada de 300 po)', 'Concentração, até 1 hora', 'Você invoca um espírito incorpóreo, esquelético ou pútrido morto-vivo que luta ao seu lado com ataques aterrorizantes.', false),
  (null, 'dnd5e', 'Invocar Sombra (Summon Shadowspawn)', 3, 'Conjuração', '1 ação', '27 metros', 'V, S, M (lágrimas em um frasco de 300 po)', 'Concentração, até 1 hora', 'Você invoca uma manifestação de sombras que causa desespero e lentidão aos inimigos ao seu redor.', false),
  (null, 'dnd5e', 'Fortaleza do Intelecto (Intellect Fortress)', 3, 'Abjuração', '1 ação', '9 metros', 'V', 'Concentração, até 1 hora', 'Você forja uma barreira mental ao redor de você ou de uma criatura voluntária dentro do alcance. O alvo ganha resistência a dano psíquico e vantagem em todas as salvaguardas de Inteligência, Sabedoria e Carisma.', false),
  (null, 'dnd5e', 'Sudário Espiritual (Spirit Shroud)', 3, 'Necromancia', '1 ação bônus', 'Pessoal', 'V, S', 'Concentração, até 1 minuto', 'Você evoca espíritos dos mortos que flutuam ao seu redor em um raio de 3 metros. Seus ataques causam 1d8 de dano extra (radiante, necrótico ou frio) e impedem que os alvos atingidos recuperem pontos de vida.', false),
  (null, 'dnd5e', 'Maremoto (Tidal Wave)', 3, 'Conjuração', '1 ação', '36 metros', 'V, S, M (uma gota de água)', 'Instantânea', 'Você invoca uma onda colossal de água que quebra em uma área de 9m de comprimento, 3m de largura e 3m de altura. Criaturas na área devem fazer salvaguarda de Destreza, sofrendo 4d8 de dano contundente e sendo derrubadas se falharem.', false),
  (null, 'dnd5e', 'Muralha de Água (Wall of Water)', 3, 'Evocação', '1 ação', '18 metros', 'V, S, M (uma gota de água)', 'Concentração, até 10 minutos', 'Você cria uma muralha de água de até 9m de comprimento, 3m de altura e 30cm de espessura. Ataques de armas à distância que passem pela muralha têm desvantagem e dano de fogo que atravesse é reduzido pela metade.', false);

-- 4º Nível (4th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Radiação Nociva (Sickening Radiance)', 4, 'Evocação', '1 ação', '36 metros', 'V, S', 'Concentração, até 10 minutos', 'Luz esverdeada e tênue ilumina uma esfera de 9 metros de raio dentro do alcance. Qualquer criatura que entrar na área ou começar seu turno nela deve fazer uma salvaguarda de Constituição. Se falhar, sofre 4d10 de dano radiante, emite luz e sofre 1 nível de exaustão.', false),
  (null, 'dnd5e', 'Sombra de Moil (Shadow of Moil)', 4, 'Necromancia', '1 ação', 'Pessoal', 'V, S, M (um olho de inseto em âmbar)', 'Concentração, até 1 minuto', 'Sombras fantasmagóricas e gélidas envolvem seu corpo, tornando você fortemente obscurecido para os outros e concedendo resistência a dano radiante. Inimigos a até 3m que acertarem você com ataques sofrem 2d8 de dano necrótico.', false),
  (null, 'dnd5e', 'Esfera da Tempestade (Storm Sphere)', 4, 'Evocação', '1 ação', '45 metros', 'V, S', 'Concentração, até 1 minuto', 'Uma esfera de ar e vento de 6 metros de raio surge em um ponto dentro do alcance. Criaturas na área sofrem 2d6 de dano contundente se falharem numa salvaguarda de Força. Como ação bônus a cada turno, você pode disparar um relâmpago da esfera causando 4d6 de dano elétrico em um alvo.', false),
  (null, 'dnd5e', 'Invocar Aberração (Summon Aberration)', 4, 'Conjuração', '1 ação', '27 metros', 'V, S, M (um tentáculo em conserva de 400 po)', 'Concentração, até 1 hora', 'Você invoca um ser aberrante do Reino Distante (Contemplador, Slaad ou Devorador de Mentes) para lutar por você.', false),
  (null, 'dnd5e', 'Invocar Construto (Summon Construct)', 4, 'Conjuração', '1 ação', '27 metros', 'V, S, M (uma pedra preciosa em engrenagem de 400 po)', 'Concentração, até 1 hora', 'Você invoca um golem de barro, pedra ou metal para esmagar seus oponentes.', false),
  (null, 'dnd5e', 'Invocar Elemental (Summon Elemental)', 4, 'Conjuração', '1 ação', '27 metros', 'V, S, M (ar, terra, fogo ou água em frasco de 400 po)', 'Concentração, até 1 hora', 'Você invoca uma encarnação elemental pura para controlar os elementos em combate.', false),
  (null, 'dnd5e', 'Invocar Demônio Maior (Summon Greater Demon)', 4, 'Conjuração', '1 ação', '18 metros', 'V, S, M (sangue de humanoide morto há 24h)', 'Concentração, até 1 hora', 'Você profere palavras blasfemas e invoca um demônio do Abismo (como um Barlgura, Tanarukk ou Chasme) sob seu comando temporário.', false);

-- 5º Nível (5th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Estática Sináptica (Synaptic Static)', 5, 'Encantamento', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Você cria uma explosão de energia psíquica pura em uma esfera de 6 metros de raio. Criaturas na área devem fazer uma salvaguarda de Inteligência. Se falharem, sofrem 8d6 de dano psíquico e subtraem 1d6 de todas as jogadas de ataque, testes de habilidade e salvaguardas de concentração por 1 minuto.', false),
  (null, 'dnd5e', 'Arma Sagrada (Holy Weapon)', 5, 'Evocação', '1 ação bônus', 'Toque', 'V, S', 'Concentração, até 1 hora', 'Você toca uma arma e a imbui com radiação divina. Enquanto a magia durar, a arma emite luz plena por 9m e seus ataques causam 2d8 de dano radiante adicional. Você pode dissipar a magia antecipadamente para criar uma explosão de 4d8 de dano radiante que cega os inimigos.', false),
  (null, 'dnd5e', 'Ataque do Vento de Aço (Steel Wind Strike)', 5, 'Conjuração', '1 ação', '9 metros', 'S, M (uma arma corpo a corpo de 1 po)', 'Instantânea', 'Você floresce a arma usada na conjuração e desaparece para desferir golpes rápidos como o vento contra até 5 alvos. Faça um ataque corpo a corpo com magia contra cada alvo. Em caso de acerto, o alvo sofre 6d10 de dano de energia. Em seguida, você se teleporta para até 1,5m de um dos alvos.', false),
  (null, 'dnd5e', 'Passo Distante (Far Step)', 5, 'Conjuração', '1 ação bônus', 'Pessoal', 'V', 'Concentração, até 1 minuto', 'Você se teleporta a até 18 metros de distância imediatamente e, como uma ação bônus em cada um de seus turnos até o final da magia, pode se teleportar outros 18 metros.', false),
  (null, 'dnd5e', 'Invocar Celestial (Summon Celestial)', 5, 'Conjuração', '1 ação', '27 metros', 'V, S, M (uma relíquia dourada de 500 po)', 'Concentração, até 1 hora', 'Você invoca um guardião celestial angelical com arco radiante ou maça sagrada.', false),
  (null, 'dnd5e', 'Invocar Espírito Dracônico (Summon Draconic Spirit)', 5, 'Conjuração', '1 ação', '18 metros', 'V, S, M (um objeto com desenho de dragão de 500 po)', 'Concentração, até 1 hora', 'Você invoca um espírito dracônico alado com sopro elemental e resistência lendária.', false),
  (null, 'dnd5e', 'Dança Macabra (Danse Macabre)', 5, 'Necromancia', '1 ação', '18 metros', 'V, S', 'Concentração, até 1 hora', 'Você imbui até 5 cadáveres Pequenos ou Médios com força profana, fazendo-os se erguer como esqueletos ou zumbis que somam seu modificador de conjuração nas jogadas de ataque e dano.', false),
  (null, 'dnd5e', 'Muralha de Luz (Wall of Light)', 5, 'Evocação', '1 ação', '36 metros', 'V, S, M (um espelho de mão)', 'Concentração, até 10 minutos', 'Uma muralha luminosa de até 18m de comprimento e 9m de altura queima e cega os inimigos que a tocarem, permitindo disparar raios de luz concentrada de 4d8 de dano radiante.', false),
  (null, 'dnd5e', 'Turbilhão (Maelstrom)', 5, 'Evocação', '1 ação', '36 metros', 'V, S, M (papel ou folha em água)', 'Concentração, até 1 minuto', 'Uma massa rodopiante de água de 9 metros de raio surge no solo, puxando as criaturas para o centro e causando 6d6 de dano contundente.', false);

-- 6º Nível (6th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Prisão Mental (Mental Prison)', 6, 'Ilusão', '1 ação', '18 metros', 'S', 'Concentração, até 1 minuto', 'Você prende a mente de uma criatura dentro do alcance em um labirinto ilusório aterrorizante. O alvo deve fazer uma salvaguarda de Inteligência. Se falhar, sofre 5d10 de dano psíquico e fica impedido e cego para tudo fora da ilusão. Se tentar se mover ou atacar através da ilusão, sofre mais 10d10 de dano psíquico.', false),
  (null, 'dnd5e', 'Jaula da Alma (Soul Cage)', 6, 'Necromancia', '1 reação (ao ver um humanoide morrer a até 18m)', '18 metros', 'V, S, M (uma pequena gaiola de prata de 100 po)', '8 horas', 'Você captura a alma de um humanoide moribundo em sua gaiola mágica. Enquanto a alma estiver presa, você pode explorá-la até 6 vezes para: curar 2d8 PV, fazer perguntas com respostas verdadeiras, ganhar vantagem em uma rolagem, ou enxergar através dos olhos que ela conhecia.', false),
  (null, 'dnd5e', 'Dispersão (Scatter)', 6, 'Conjuração', '1 ação', '9 metros', 'V', 'Instantânea', 'O ar treme quando você escolhe até cinco criaturas que possa ver dentro do alcance. Criaturas involuntárias devem fazer uma salvaguarda de Sabedoria. Você teleporta cada criatura afetada para um espaço desocupado à sua escolha a até 36 metros de onde ela estava.', false),
  (null, 'dnd5e', 'Disfarce de Outro Mundo de Tasha (Tasha''s Otherworldly Guise)', 6, 'Transmutação', '1 ação bônus', 'Pessoal', 'V, S, M (um cálice de 500 po)', 'Concentração, até 1 minuto', 'Você canaliza a magia dos Planos Superiores ou Inferiores, ganhando imunidade a dano de fogo e veneno (Inferior) ou radiante e necrótico (Superior), deslocamento de voo de 12 metros, +2 na CA e a habilidade de atacar usando seu atributo de conjuração com ataque extra.', false),
  (null, 'dnd5e', 'Invocar Ínfero (Summon Fiend)', 6, 'Conjuração', '1 ação', '27 metros', 'V, S, M (sangue humanoide em frasco de rubi de 600 po)', 'Concentração, até 1 hora', 'Você invoca um demônio, diabo ou yugoloth implacável que luta ao seu lado.', false),
  (null, 'dnd5e', 'Ossos da Terra (Bones of the Earth)', 6, 'Transmutação', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Você faz até seis pilares de pedra de 1,5m de diâmetro e até 9m de altura brotarem do solo. Criaturas pegas sob os pilares sofrem 6d6 de dano contundente se forem esmagadas contra o teto.', false);

-- 7º Nível (7th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Coroa de Estrelas (Crown of Stars)', 7, 'Evocação', '1 ação', 'Pessoal', 'V, S', '1 hora', 'Sete partículas semelhantes a estrelas brilhantes orbitam sua cabeça. Enquanto a magia durar, como ação bônus, você pode arremessar uma dessas estrelas contra um alvo a até 36 metros, fazendo um ataque mágico à distância que causa 4d12 de dano radiante ao acertar.', false),
  (null, 'dnd5e', 'Templo dos Deuses (Temple of the Gods)', 7, 'Conjuração', '1 hora', '36 metros', 'V, S, M (um símbolo sagrado de 500 po)', '24 horas', 'Você manifesta um templo sagrado protegido contra tipos de criaturas profanas, onde magias de adivinhação não penetram e aliados recebem cura potencializada.', false),
  (null, 'dnd5e', 'Palavra de Poder: Dor (Power Word Pain)', 7, 'Encantamento', '1 ação', '18 metros', 'V', 'Instantânea', 'Você profere uma palavra de poder que causa dores lancinantes em uma criatura com 100 pontos de vida ou menos. O deslocamento do alvo cai para 3m, ele tem desvantagem em todas as jogadas e não pode conjurar magias sem passar em salvaguarda de Constituição.', false),
  (null, 'dnd5e', 'Sonho do Véu Azul (Dream of the Blue Veil)', 7, 'Conjuração', '10 minutos', '6 metros', 'V, S, M (um item mágico de outro mundo de 500 po)', 'Concentração, até 6 horas', 'Você e até oito criaturas voluntárias entram em transe e viajam através do véu interplanetário para outro mundo do Multiverso (como Faerûn, Eberron, Krynn, Ravnica, etc.).', false);

-- 8º Nível (8th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Escuridão Enlouquecedora (Maddening Darkness)', 8, 'Evocação', '1 ação', '45 metros', 'V, M (uma gota de piche misturada com sangue)', 'Concentração, até 10 minutos', 'Uma esfera de escuridão mágica impenetrável de 18 metros de raio surge no alcance, repleta de gritos e sussurros perturbadores. Criaturas na área sofrem 8d8 de dano psíquico se falharem em uma salvaguarda de Sabedoria.', false),
  (null, 'dnd5e', 'Dragão Ilusório (Illusory Dragon)', 8, 'Ilusão', '1 ação', '18 metros', 'S', 'Concentração, até 1 minuto', 'Você cria uma ilusão sensorial colossal de um dragão temível. Criaturas que o veem ficam amedrontadas e, a cada turno, o dragão pode disparar um sopro ilusório causando 7d6 de dano.', false),
  (null, 'dnd5e', 'Ressecamento Horrível de Abi-Dalzim (Abi-Dalzim''s Horrid Wilting)', 8, 'Necromancia', '1 ação', '45 metros', 'V, S, M (uma esponja seca)', 'Instantânea', 'Você extrai a umidade de todas as criaturas em um cubo de 9 metros. Cada criatura na área deve fazer uma salvaguarda de Constituição, sofrendo 10d8 de dano necrótico se falhar (ou metade se passar). Plantas e elementais de água têm desvantagem.', false);

-- 9º Nível (9th Level)
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
  (null, 'dnd5e', 'Lâmina do Desastre (Blade of Disaster)', 9, 'Conjuração', '1 ação bônus', '18 metros', 'V, S', 'Concentração, até 1 minuto', 'Você cria uma fenda plana em forma de espada no tecido da realidade. Ela causa 4d12 de dano de energia com margem de crítico expandida (18-20, causando 12d12 de dano). Como ação bônus em turnos subsequentes, você pode movê-la 9m e atacar duas vezes.', false),
  (null, 'dnd5e', 'Grito Psíquico (Psychic Scream)', 9, 'Encantamento', '1 ação', '27 metros', 'S', 'Instantânea', 'Você desencadeia o poder da sua mente para explodir os pensamentos de até 10 criaturas à sua escolha. Cada alvo deve fazer uma salvaguarda de Inteligência. Se falhar, sofre 14d6 de dano psíquico e fica atordoado. Se o dano matar uma criatura, sua cabeça explode.', false),
  (null, 'dnd5e', 'Metamorfose em Massa (Mass Polymorph)', 9, 'Transmutação', '1 ação', '36 metros', 'V, S, M (uma lagarta em casulo)', 'Concentração, até 1 hora', 'Você transforma até dez criaturas voluntárias ou involuntárias em feras de ND até igual ao nível delas por até 1 hora.', false),
  (null, 'dnd5e', 'Invulnerabilidade (Invulnerability)', 9, 'Abjuração', '1 ação', 'Pessoal', 'V, S, M (um pedaço pequeno de adamantina de 500 po)', 'Concentração, até 10 minutos', 'Você fica imune a todo e qualquer tipo de dano enquanto a magia durar.', false);
